class Solution {
  public long countPairs(int[] nums, int k) {
    Map<Integer, Long> byGcd = new HashMap<>();
    for (int x : nums) byGcd.merge(gcd(x, k), 1L, Long::sum);
    List<Integer> keys = new ArrayList<>(byGcd.keySet());
    long pairs = 0;
    for (int i = 0; i < keys.size(); i++) {
      for (int j = i; j < keys.size(); j++) {
        int a = keys.get(i), b = keys.get(j);
        // x * y is divisible by k exactly when gcd(x, k) * gcd(y, k) is
        if ((long) a * b % k != 0) continue;
        long ca = byGcd.get(a), cb = byGcd.get(b);
        pairs += i == j ? ca * (ca - 1) / 2 : ca * cb;
      }
    }
    return pairs;
  }

  private int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
  }
}
